        "name": "change-password-dialog.tsx",
        "code": "\"use client\"\n\nimport { revalidateLogic } from \"@tanstack/react-form\"\nimport { type ReactNode, useId, useMemo } from \"react\"\n\nimport { FieldGroup } from \"@/components/ui/field\"\nimport {\n  FormDialog,\n  FormDialogBody,\n  FormDialogCancel,\n  FormDialogDescription,\n  FormDialogError,\n  FormDialogFooter,\n  FormDialogForm,\n  FormDialogHeader,\n  FormDialogSubmit,\n  FormDialogTitle,\n} from \"@/components/openlmis/form-dialog/form-dialog\"\nimport { useDialogTarget } from \"@/components/openlmis/form-dialog/use-dialog-target\"\nimport { useAppForm } from \"@/components/openlmis/form-fields/form\"\nimport { PasswordRequirements } from \"@/components/openlmis/password-requirements/password-requirements\"\nimport type { PasswordOwner } from \"@/components/openlmis/password-requirements/password-rules\"\nimport { newPasswordSchema } from \"@/components/openlmis/password-requirements/password-schema\"\n\n// Re-exported so existing imports from this block keep working.\nexport { newPasswordSchema }\n\ntype ChangePasswordDialogProps = {\n  open: boolean\n  /** Whose password it is; its username also lets a password manager file the new one. */\n  user: PasswordOwner\n  /** Called with the new password; change it, then close, e.g. by signing out. */\n  onSubmit: (password: string) => void\n  /** Keeps the dialog open and shows a spinner while the password is changed. */\n  pending?: boolean\n  /** Shown above the fields, e.g. why the change was refused. */\n  error?: ReactNode\n  onClose: () => void\n}\n\nexport function ChangePasswordDialog({\n  open,\n  user,\n  onSubmit,\n  pending = false,\n  error,\n  onClose,\n}: ChangePasswordDialogProps) {\n  const { shown, dialogProps } = useDialogTarget(\n    open ? true : undefined,\n    onClose\n  )\n\n  return (\n    <FormDialog {...dialogProps(pending)}>\n      {shown && (\n        <ChangePasswordForm\n          error={error}\n          onSubmit={onSubmit}\n          pending={pending}\n          user={user}\n        />\n      )}\n    </FormDialog>\n  )\n}\n\nfunction ChangePasswordForm({\n  user,\n  onSubmit,\n  pending,\n  error,\n}: Pick<ChangePasswordDialogProps, \"user\" | \"onSubmit\" | \"error\"> & {\n  pending: boolean\n}) {\n  const requirementsId = useId()\n  const schema = useMemo(() => newPasswordSchema(user), [user])\n  const form = useAppForm({\n    defaultValues: { password: \"\", confirm: \"\" },\n    // Quiet until the first submit, then each field re-checks as it is corrected.\n    validationLogic: revalidateLogic({\n      mode: \"submit\",\n      modeAfterSubmission: \"change\",\n    }),\n    validators: { onDynamic: schema },\n    onSubmit: ({ value }) => onSubmit(value.password),\n  })\n\n  return (\n    <FormDialogForm onSubmit={form.handleSubmit}>\n      <FormDialogHeader>\n        <FormDialogTitle>Change Password</FormDialogTitle>\n        <FormDialogDescription>\n          After changing it you will be signed out, so you can sign in with the\n          new password.\n        </FormDialogDescription>\n      </FormDialogHeader>\n      <FormDialogBody>\n        <FieldGroup>\n          {error && (\n            <FormDialogError\n              description={error}\n              title=\"Could Not Change Password\"\n            />\n          )}\n          {/* Lets password managers file the new password under the right account. */}\n          <input\n            autoComplete=\"username\"\n            hidden\n            readOnly\n            value={user.username}\n          />\n          <form.AppField name=\"password\">\n            {(field) => (\n              <div className=\"grid gap-3\">\n                <field.PasswordField\n                  describedBy={requirementsId}\n                  label=\"New Password\"\n                  required\n                />\n                <PasswordRequirements\n                  id={requirementsId}\n                  owner={user}\n                  password={field.state.value}\n                />\n              </div>\n            )}\n          </form.AppField>\n          <form.AppField name=\"confirm\">\n            {(field) => (\n              <field.PasswordField label=\"Confirm New Password\" required />\n            )}\n          </form.AppField>\n        </FieldGroup>\n      </FormDialogBody>\n      <FormDialogFooter>\n        <FormDialogCancel disabled={pending} />\n        <FormDialogSubmit pending={pending}>Change Password</FormDialogSubmit>\n      </FormDialogFooter>\n    </FormDialogForm>\n  )\n}",
        "lang": "tsx",
        "target": "components/openlmis/profile-page/change-password-dialog.tsx"
