        "code": "import { ServiceAccountsPage } from \"@/components/openlmis/service-accounts-page/service-accounts-page\"\n\n// A Next.js App Router route; in any other React app, render ServiceAccountsPage from your own route.\nexport default function Page() {\n  return <ServiceAccountsPage />\n}",
        "lang": "tsx",
        "target": "app/service-accounts-page/page.tsx"
